<script setup lang="ts">
import {onMounted,ref,reactive,computed} from 'vue';
import {useRouter} from 'vue-router';
import api from '../api';
import {advisorContext} from '../shoppingContext';
const router=useRouter();
const rows=ref<any[]>([]), catalog=ref<any[]>([]), busy=ref(false), message=ref('');
const loadError=ref(false), compareIds=ref<number[]>([]), historyRows=ref<any[]>([]), historyPlan=ref<any>(null), historyLoading=ref(false);
const listLoading=ref(false), historyError=ref('');
const compared=computed(()=>rows.value.filter(p=>compareIds.value.includes(p.id)));
const scenes=['地面清洁','擦窗机器人','庭院与泳池','陪伴娱乐','航拍无人机','教育编程','四足机器人','人形机器人','商用服务','机器人配件'];
const candidateQuery=ref('');
const draft=reactive({id:null as number|null,title:'',requirement:'',note:'',budget:'' as string|number,scene:'',productIds:[] as number[]});
function reset(){Object.assign(draft,{id:null,title:'',requirement:'',note:'',budget:'',scene:'',productIds:[]});candidateQuery.value='';}
async function load(){listLoading.value=true;const recovering=loadError.value;try{rows.value=await api.get('/shopping-plans') as any[];loadError.value=false;if(recovering)message.value='计划列表已重新读取。';compareIds.value=compareIds.value.filter(id=>rows.value.some(p=>p.id===id));return true;}catch(e:any){loadError.value=true;message.value=`计划列表读取失败：${e.message}`;return false;}finally{listLoading.value=false;}}
async function showHistory(p:any){if(historyLoading.value||busy.value)return;historyPlan.value=p;historyRows.value=[];historyLoading.value=true;historyError.value='';try{historyRows.value=await api.get(`/shopping-plans/${p.id}/versions`) as any[];}catch(e:any){historyError.value=e.message;}finally{historyLoading.value=false;}}
function restore(version:any){if(busy.value)return;if(!confirm('将此历史版本载入编辑框？当前未保存的编辑会被替换；点击更新计划后才会写入。'))return;edit({...version.snapshot,id:historyPlan.value.id});message.value='历史版本已载入编辑框，核对后点击更新计划；当前已保存版本尚未改变。';document.getElementById('plan-title')?.focus();}
function ids(p:any){return String(p.productIds||'').split(',').filter(Boolean).map(Number);}
function edit(p:any){Object.assign(draft,p,{budget:p.budget??'',scene:p.scene||'',productIds:ids(p)});}
async function save(){if(busy.value)return;busy.value=true;message.value='';const submitted=JSON.stringify(draft);try{const saved:any=await api.post('/shopping-plans',JSON.parse(submitted));sessionStorage.removeItem('robotmall-plan-draft');const unchanged=JSON.stringify(draft)===submitted;if(unchanged)reset();else draft.id=saved.id;historyPlan.value=null;const refreshed=await load();message.value=(unchanged?'计划已保存。':'上一版计划已保存；编辑框中刚修改的内容仍待保存。')+(refreshed?'':'但列表刷新失败，请重新读取列表，不要重复新建。');}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
async function remove(p:any){if(busy.value||!confirm(`删除“${p.title}”及其历史版本？此操作不可恢复。`))return;busy.value=true;try{await api.delete(`/shopping-plans/${p.id}`);if(draft.id===p.id)reset();if(historyPlan.value?.id===p.id)historyPlan.value=null;const refreshed=await load();if(!refreshed)message.value='删除已成功，但列表刷新失败，请重新读取。';}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
function resume(p:any){const question=[p.requirement,p.scene?`本次场景：${p.scene}。`:'',p.budget?`本次预算上限${p.budget}元，不允许自动超预算。`:''].filter(Boolean).join('\n');if(question.length>800){message.value='需求加预算场景后超过800字，请先编辑缩短需求再咨询，原计划不会丢失。';return;}advisorContext(ids(p).map(id=>({id})),question);router.push('/advisor');}
onMounted(async()=>{
try{const d=JSON.parse(sessionStorage.getItem('robotmall-plan-draft')||'null');const owner=JSON.parse(localStorage.getItem('user')||'null')?.id;if(d && (d.owner===owner || d.owner==null)){draft.requirement=String(d.requirement||'').slice(0,800);draft.productIds=Array.isArray(d.productIds)?d.productIds.filter((id:number)=>Number.isSafeInteger(id)&&id>0).slice(0,4):[];}else sessionStorage.removeItem('robotmall-plan-draft');}catch{sessionStorage.removeItem('robotmall-plan-draft');}
await load();try{catalog.value=await api.get('/products') as any[];}catch(e:any){message.value='候选目录读取失败，请刷新后再选择；原候选编号保留。'+e.message;}});
</script>
<template><section class="profile-section plan-panel" id="plans"><div class="profile-section-head"><div><h2>我的选购计划</h2><p>主动保存需求与候选，下次继续。仅当前账号可读写，不会自动建立画像。</p></div></div><p v-if="message" role="status">{{ message }}</p>
<form class="plan-form" @submit.prevent="save">
<div v-if="loadError" role="alert"><p>列表暂未读取成功，不代表没有计划。</p><button class="btn secondary" type="button" @click="load" :disabled="busy">重新读取计划</button></div>
<section v-if="compared.length" class="plan-comparison" aria-label="计划比较"><h3>比较选购计划（最多3份）</h3><p>这里只比较保存的需求和候选，不把不同品类商品直接排名。</p><div class="plan-comparison-grid"><article v-for="p in compared" :key="p.id"><h4>{{ p.title }}</h4><dl><dt>预算上限</dt><dd>{{ p.budget ? `¥${p.budget}` : '未设置' }}</dd><dt>使用场景</dt><dd>{{ p.scene || '未限定' }}</dd><dt>需求</dt><dd>{{ p.requirement }}</dd><dt>候选</dt><dd>{{ ids(p).map(id=>catalog.find(x=>x.id===id)?.name||`商品${id}（可能已下架）`).join('、') || '未选择' }}</dd><dt>我的备注</dt><dd>{{ p.note || '未填写' }}</dd></dl><button type="button" class="btn secondary" @click="compareIds=compareIds.filter(id=>id!==p.id)">移出比较</button></article></div></section>
<section v-if="historyPlan" class="plan-versions" aria-label="版本记录"><h3>{{ historyPlan.title }} · 版本记录</h3><p>最多保留最近20次保存；载入历史版本后，核对并保存才会恢复。</p><p v-if="historyLoading">正在读取历史…</p><p v-else-if="historyError" role="alert">版本读取失败：{{ historyError }}<button type="button" class="btn secondary" @click="showHistory(historyPlan)">重试版本读取</button></p><p v-else-if="!historyRows.length">暂无版本记录；旧计划将在下次成功保存时开始记录。</p><article v-for="v in historyRows" :key="v.id"><div><strong>{{ v.snapshot.title }}</strong><small>{{ String(v.createdAt).replace('T',' ').slice(0,19) }}</small><p>{{ v.snapshot.scene || '未限定场景' }} · {{ v.snapshot.budget ? `¥${v.snapshot.budget}` : '预算未设置' }}</p><details><summary>查看需求与备注</summary><p>{{ v.snapshot.requirement }}</p><p>{{ v.snapshot.note || '未填写备注' }}</p></details></div><button type="button" class="btn secondary" :disabled="busy" @click="restore(v)">载入此版本编辑</button></article><button type="button" class="btn secondary" @click="historyPlan=null">关闭版本记录</button></section>
<label>计划名称<input id="plan-title" class="input" v-model.trim="draft.title" maxlength="60" required placeholder="例如：客厅清洁机器人" /></label>
<div class="plan-fields"><label>预算上限（元，可留空）<input class="input" type="number" min="0.01" max="10000000" step="0.01" v-model="draft.budget" placeholder="例如：4000" /></label><label>使用场景<select class="input" v-model="draft.scene" aria-label="使用场景"><option value="">暂不限定</option><option v-for="scene in scenes" :key="scene">{{ scene }}</option></select></label></div>
<p class="muted">继续助选时使用这里的预算上限，不会自动放宽。旧计划仍可保留文字需求，建议把预算更新到上方字段以免表述冲突。</p>
<div v-if="draft.productIds.length" class="plan-selected-removal" aria-label="管理已选候选"><button v-for="id in draft.productIds" :key="id" type="button" class="btn secondary" @click="draft.productIds=draft.productIds.filter(pid=>pid!==id)">{{ catalog.find(p=>p.id===id)?.name || `商品${id}（可能已下架）` }} · 移除</button></div>
<label>需求与预算<textarea class="input" v-model.trim="draft.requirement" maxlength="800" required placeholder="使用环境、必须满足的功能，以及自己的顾虑" /></label><label>我的备注<textarea class="input" v-model.trim="draft.note" maxlength="800" placeholder="记录自己的考虑，不会自动发送给 AI" /></label>
<fieldset><legend>候选商品（最多4款，可留空）</legend><label>查找候选<input class="input" v-model.trim="candidateQuery" placeholder="输入型号或品牌；筛选不清除已选项" /></label><p>已选 {{ draft.productIds.length }}/4 款</p><div class="plan-candidates"><label v-for="p in catalog.filter(p=>!candidateQuery || `${p.name} ${p.brandName}`.toLowerCase().includes(candidateQuery.toLowerCase()))" :key="p.id"><input type="checkbox" :value="p.id" v-model="draft.productIds" :disabled="!draft.productIds.includes(p.id)&&draft.productIds.length>=4" />{{ p.name }}</label></div><p v-if="draft.productIds.length">已选：{{ draft.productIds.map(id=>catalog.find(p=>p.id===id)?.name||`商品${id}（可能已下架）`).join('、') }}</p></fieldset><div class="plan-actions"><button class="btn" :disabled="busy">{{ draft.id?'更新计划':'保存计划' }}</button><button type="button" class="btn secondary" @click="reset" :disabled="busy">新建／清空编辑</button></div></form>
<div class="plan-list"><p v-if="!listLoading && !loadError && !rows.length">还没有保存的计划，可以从 AI 助选带入，或在这里新建。</p><article v-for="p in rows" :key="p.id"><label class="plan-compare-pick"><input type="checkbox" :value="p.id" v-model="compareIds" :disabled="!compareIds.includes(p.id)&&compareIds.length>=3" />加入计划比较</label><h3>{{ p.title }}</h3><p v-if="p.scene || p.budget">场景：{{ p.scene || '暂不限定' }} · 预算上限：{{ p.budget ? `¥${p.budget}` : '未设置' }}</p><p>{{ p.requirement }}</p><p v-if="p.note">我的备注：{{ p.note }}</p><div class="plan-products"><router-link v-for="id in ids(p)" :key="id" :to="`/product/${id}`">{{ catalog.find(x=>x.id===id)?.name || `商品${id}（可能已下架）` }}</router-link></div><small>更新于 {{ String(p.updatedAt).replace('T',' ').slice(0,16) }}</small><div class="plan-actions"><button class="btn secondary" @click="showHistory(p)" :disabled="busy || historyLoading">版本记录</button><button class="btn secondary" @click="resume(p)">继续助选</button><router-link v-if="ids(p).length" class="btn secondary" :to="{path:'/compare',query:{ids:ids(p).join(',')}}">比较候选</router-link><button class="btn secondary" @click="edit(p)" :disabled="busy">编辑</button><button class="btn secondary" @click="remove(p)" :disabled="busy">删除</button></div></article></div></section></template>
